<script setup>import AppShell from'../../Layouts/AppShell.vue';import GroupNav from'../../Components/GroupNav.vue';import PageHeader from'../../Components/PageHeader.vue';import UiBadge from'../../Components/UiBadge.vue';import UiButton from'../../Components/UiButton.vue';import UiModal from'../../Components/UiModal.vue';import{Head,router}from'@inertiajs/vue3';import{ref}from'vue';const p=defineProps({group:Object,invites:Array}),pending=ref(null),busy=ref(false);function act(kind,invite,data={}){busy.value=true;router.post(`/groups/${p.group.id}/access-invites/${invite.id}/${kind}`,data,{preserveScroll:true,onFinish:()=>{busy.value=false;pending.value=null}})}async function copy(invite){await navigator.clipboard.writeText(invite.url)}</script>
<template><AppShell><Head title="Group Invitations"/><GroupNav :group="group"/><div class="lp-page mt-6"><PageHeader eyebrow="Group access" :title="`Invitations · ${group.name}`" description="Invitation codes and links are scoped to this Group. Revoking an invitation does not remove accepted participants."/><div class="mt-8 grid gap-5 md:grid-cols-2"><UiCard v-for="invite in invites" :key="invite.id"><div class="flex justify-between gap-3"><h2 class="font-bold">{{invite.label}}</h2><UiBadge :tone="invite.active?'success':'error'">{{invite.active?'Active':'Unavailable'}}</UiBadge></div><p class="mt-4 font-mono text-2xl font-bold tracking-widest text-indigo">{{invite.code}}</p><p class="mt-3 text-sm text-slate-500">Used {{invite.used_count}}{{invite.max_uses?` of ${invite.max_uses}`:''}}</p><div class="mt-5 flex flex-wrap gap-2"><UiButton variant="secondary" @click="copy(invite)">Copy secure link</UiButton><a class="btn-secondary" target="_blank" rel="noopener" :href="`/groups/${group.id}/access-invites/${invite.id}/print`">Print QR</a><UiButton v-if="invite.active" variant="danger" @click="pending=invite">Revoke</UiButton><UiButton v-else @click="act('reactivate',invite)">Reactivate</UiButton></div></UiCard></div><UiModal :open="!!pending" title="Revoke invitation?" description="The code and link will stop accepting new participants. Existing members keep their access." :busy="busy" @close="pending=null" @confirm="act('revoke',pending)"/></div></AppShell></template>
